const PASSWORD = process.env.FAKE_PW || "hunter2";
const PORT = Number(process.env.FAKE_PORT || 27299);
const HOST = process.env.FAKE_HOST || "127.0.0.1";
const DYNAMIC = process.env.FAKE_DYNAMIC === "1";

